@RestController
@RequestMapping("/api/orders")
public class OrderController {

    @GetMapping("/{id}")
    public Order getOrder(@PathVariable Long id) {
        // DispatcherServlet already intercepted this request
        // HandlerMapping found this method matches GET /api/orders/{id}
        // Now control reaches here
        return new Order(id, "Laptop", 1200.0);
        // DispatcherServlet will use Jackson to convert Order to JSON
    }
}

record Order(Long id, String item, Double price) {}

