@RestController
@RequestMapping("/api/products")
public class ProductController {

    @GetMapping("/{id}")
    public Product getProduct(@PathVariable Long id) {
        // RequestMappingHandlerMapping mapped GET /api/products/123 to this method
        return new Product(id, "Gaming Mouse", 59.99);
    }

    @PostMapping
    public Product createProduct(@RequestBody Product product) {
        // POST /api/products mapped here by HTTP method
        return product;
    }
}

record Product(Long id, String name, Double price) {}

// During startup, RequestMappingHandlerMapping scans this controller:
// Map entry: GET /api/products/{id} -> ProductController.getProduct(Long)
// Map entry: POST /api/products -> ProductController.createProduct(Product)
