@Component
public class RequestTimingInterceptor implements HandlerInterceptor {

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        var startTime = System.currentTimeMillis();
        request.setAttribute("startTime", startTime); // Store for later
        return true; // Continue to controller; return false to short-circuit
    }

    @Override
    public void postHandle(HttpServletRequest request, HttpServletResponse response, Object handler, ModelAndView modelAndView) {
        // Controller method executed successfully, but response not sent yet
        // Can modify ModelAndView here for traditional MVC apps
    }

    @Override
    public void afterCompletion(HttpServletRequest request, HttpServletResponse response, Object handler, Exception ex) {
        var startTime = (Long) request.getAttribute("startTime");
        var duration = System.currentTimeMillis() - startTime;
        System.out.printf("[%s %s] completed in %d ms%n", request.getMethod(), request.getRequestURI(), duration);
        // Runs even if controller throws exception
    }
}

@Configuration
class WebConfig implements WebMvcConfigurer {
    @Autowired private RequestTimingInterceptor timingInterceptor;

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(timingInterceptor).addPathPatterns("/api/**");
    }
}

@RestController
@RequestMapping("/api/orders")
public class OrderController {
    @Autowired
    private OrderService orderService;

    @PostMapping
    public OrderResponse createOrder(@RequestBody OrderRequest request) {
        // MappingJackson2HttpMessageConverter deserializes JSON → OrderRequest
        var order = orderService.create(request.userId(), request.items());
        // Same converter serializes OrderResponse → JSON response body
        return new OrderResponse(order.id(), order.total(), "CREATED");
    }
}

record OrderRequest(Long userId, List<String> items) {}
record OrderResponse(Long orderId, Double total, String status) {}

// When client sends: POST /api/orders with Content-Type: application/json
// Converter reads JSON bytes → OrderRequest object
// When method returns OrderResponse, converter writes object → JSON bytes
